Result<Unit,Text> exercise() {
    Text input = Args.get(0)?;
    Text requested = Args.get(1)?;
    int rounds = requested.parseInt()?;
    long total = 0L;
    int index = 0;
    while (index < rounds) {
        Text content = Files.readText(input)?;
        total = total + (long)content.byteLength();
        index = index + 1;
    }
    println(total);
    return new Result<Unit,Text>.Ok(());
}
void main() {
    match (exercise()) {
        Ok(unit) { println("DONE"); }
        Err(error) { Console.print("ERROR: "); Console.printText(error); println(""); }
    }
}
